    if not names or len(set(names))!=len(names) or any(name not in ('cpu','schedstat','softnet','netdev','infiniband') for name in names):raise ValueError('review collector scope before extending')
    root=pathlib.Path(root);(root/'proc').mkdir(exist_ok=True);(root/'sys').mkdir(exist_ok=True)
