    assert version.returncode==0 and 'version 1.9.1' in version.stdout+version.stderr
    with socket.socket() as sock:sock.bind(('127.0.0.1',0));port=sock.getsockname()[1]
    log=(root/'exporter.log').open('wb')
    args=['node_exporter','--web.listen-address=127.0.0.1:'+str(port),'--collector.disable-defaults',*['--collector.'+name for name in names],'--path.procfs='+str(root/'proc'),'--path.sysfs='+str(root/'sys')]
    if 'netdev' in names:args.append('--no-collector.netdev.netlink')
    process=subprocess.Popen(args,stdout=log,stderr=log,env={**os.environ,'GOMAXPROCS':'2','GOMEMLIMIT':'64MiB'})
    opener=urllib.request.build_opener(urllib.request.ProxyHandler({}))
    def scrape():
        with opener.open('http://127.0.0.1:'+str(port)+'/metrics',timeout=2) as response:text=response.read().decode()
        assert all('node_scrape_collector_success{collector="'+name+'"} 1' in text for name in names),'native collector rejected owned fixture: '+(root/'exporter.log').read_text(errors='replace')[-2000:]
        rows=[]
        for line in text.splitlines():
            if not line.startswith('node_') or line.startswith('#'):continue
            match=re.fullmatch(r'([a-zA-Z_:][a-zA-Z0-9_:]*)(?:\{([^}]*)\})?\s+([^ ]+)',line)
            if match:rows.append((match[1],dict(re.findall(r'([a-zA-Z_][a-zA-Z0-9_]*)="([^"]*)"',match[2] or '')),float(match[3])))
        return rows
    try:
        for _ in range(100):
            assert process.poll() is None,(root/'exporter.log').read_text(errors='replace')[-2000:]
            try:scrape();break
            except OSError:time.sleep(.02)
        else:raise AssertionError('private exporter HTTP readiness failed')
        print('NATIVE_NODE_EXPORTER_191_COLLECTOR_READY:'+','.join(names),flush=True)
        yield scrape
    finally:
        if process.poll() is None:process.terminate()
        try:process.wait(timeout=3)
