    if any(value<0 for value in delta.values()):raise ValueError('counter reset')
    factor=4 if previous['origin']=='sysfs_words' else 1
    return dict(rx_bytes_per_second=delta['rx_data']*factor/seconds,tx_bytes_per_second=delta['tx_data']*factor/seconds,rx_packets_per_second=delta['rx_packets']/seconds)
